# SQL Governance - sealed Development dependency ingress for SQLGlot.
# This capability owns exactly one requirements mutation and accepts no paths,
# package names, versions, commands, SQL, or arbitrary Worker actions.
_SQLGLOT_DEP_CAPABILITY = "SQLGLOT_DEPENDENCY_DEVELOPMENT"
_SQLGLOT_DEP_CONTEXT = "SQL_GOVERNANCE"
_SQLGLOT_DEP_AUTH_REF = "sqlglot-gate0b-certified-readonly-20261120"
_SQLGLOT_DEP_REQUIREMENTS = "backend/requirements.txt"
_SQLGLOT_DEP_LINE = "sqlglot==30.33.0\n"


def _sqlglot_dependency_development_builder(request: Mapping[str, Any]) -> dict[str, Any]:
    context = _g3_context(request)
    if context != _SQLGLOT_DEP_CONTEXT:
        raise SemanticCapabilityError("SEMANTIC_BOUNDED_CONTEXT_UNSUPPORTED")

    c = _g3_constraints(request, {"authorization_ref"})
    if c.get("authorization_ref") != _SQLGLOT_DEP_AUTH_REF:
        raise SemanticCapabilityError("SEMANTIC_SQLGLOT_AUTHORIZATION_REQUIRED")

    requirements_path = _DEV_REPO_ROOT / _SQLGLOT_DEP_REQUIREMENTS
    if not requirements_path.is_file():
        raise SemanticCapabilityError("SEMANTIC_SQLGLOT_REQUIREMENTS_MISSING")

    current = requirements_path.read_text(encoding="utf-8")
    if _SQLGLOT_DEP_LINE.strip() in {line.strip() for line in current.splitlines()}:
        raise SemanticCapabilityError("SEMANTIC_SQLGLOT_DEPENDENCY_ALREADY_PRESENT")
    if any(line.strip().lower().startswith("sqlglot") for line in current.splitlines()):
        raise SemanticCapabilityError("SEMANTIC_SQLGLOT_DEPENDENCY_VERSION_CONFLICT")

    anchor = "SQLAlchemy==2.0.50\n"
    if current.count(anchor) != 1:
        raise SemanticCapabilityError("SEMANTIC_SQLGLOT_REQUIREMENTS_ANCHOR_DRIFT")

    updated = current.replace(anchor, anchor + _SQLGLOT_DEP_LINE, 1)
    source_sha = _gate_b_hashlib.sha256(current.encode("utf-8")).hexdigest()

    return {
        "actions": [{
            "type": "write_file",
            "path": _SQLGLOT_DEP_REQUIREMENTS,
            "content": updated,
            "source_sha256": source_sha,
            "expected_sha256": source_sha,
        }],
        "checks": [{"type": "git_diff_check"}],
        "scheduling": {
            **_g3_scheduling(context),
            "conflict_domains": ["GLOBAL_GIT_WRITER", context],
        },
    }


register_capability(
    SemanticCapability(
        code=_SQLGLOT_DEP_CAPABILITY,
        modes=("MUTATION",),
        builder=_sqlglot_dependency_development_builder,
    )
)

_CAPABILITY_METADATA[_SQLGLOT_DEP_CAPABILITY] = {
    "bounded_context_rule": _SQLGLOT_DEP_CONTEXT,
    "allowed_constraints": ("authorization_ref",),
    "allowed_path_roots": (),
}

def test_sqlglot_dependency_capability_is_sealed_and_fixed(monkeypatch, tmp_path):
    cap = sem_caps.resolve_capability("SQLGLOT_DEPENDENCY_DEVELOPMENT")
    assert cap.modes == ("MUTATION",)

    requirements = tmp_path / "requirements.txt"
    requirements.write_text("SQLAlchemy==2.0.50\nstarlette==0.37.2\n", encoding="utf-8")
    monkeypatch.setattr(sem_caps, "_DEV_REPO_ROOT", tmp_path)

    payload = cap.builder({
        "bounded_context": "SQL_GOVERNANCE",
        "constraints": {
            "authorization_ref": "sqlglot-gate0b-certified-readonly-20261120",
        },
    })

    assert payload["actions"][0]["path"] == "backend/requirements.txt"
    assert payload["actions"][0]["type"] == "write_file"
    assert "sqlglot==30.33.0\n" in payload["actions"][0]["content"]
    assert payload["checks"] == [{"type": "git_diff_check"}]


def test_sqlglot_dependency_capability_rejects_arbitrary_constraints():
    cap = sem_caps.resolve_capability("SQLGLOT_DEPENDENCY_DEVELOPMENT")
    with pytest.raises(sem_caps.SemanticCapabilityError):
        cap.builder({
            "bounded_context": "SQL_GOVERNANCE",
            "constraints": {
                "authorization_ref": "sqlglot-gate0b-certified-readonly-20261120",
                "path": "backend/requirements.txt",
            },
        })
